"""Independently audit the declared ten natural-GC runs and write JSON plus Markdown."""

import argparse
import hashlib
import json
import os
from pathlib import Path
import re


MAIN = "org.eclipse.rdf4j.sail.lmdb.evaluation.NativeDirectMemoNaturalGcDiagnostic"
MASK64 = (1 << 64) - 1
HASH_SEED = 0xCBF29CE484222325
HASH_MULTIPLIER = 0x100000001B3
EXPECTED = {(arm, chars, consumer) for arm in ("strong", "weak")
            for chars in (1024, 1048577) for consumer in ("none", "one")}
EXPECTED |= {("ordinary", chars, "none") for chars in (1024, 1048577)}
EXPLICIT_GC = re.compile(r"System\.gc|Diagnostic Command|Heap (?:Inspection|Dump) Initiated GC", re.IGNORECASE)


def require(condition, message):
    if not condition:
        raise AssertionError(message)


def sha(path):
    with path.open("rb") as handle:
        return hashlib.file_digest(handle, "sha256").hexdigest()


def slot(identifier):
    value = (identifier ^ ((4 * 0x9E3779B97F4A7C15) & MASK64)) & MASK64
    value ^= value >> 33
    value = value * 0xFF51AFD7ED558CCD & MASK64
    value ^= value >> 33
    value = value * 0xC4CEB9FE1A85EC53 & MASK64
    value ^= value >> 33
    return value & 4095


def checksum_from_primitives(keys, characters):
    """Recreate the lexical oracle without reading a Value or a native store."""
    checksum = HASH_SEED
    for key in keys:
        prefix = f"urn:natural-gc-memo:{key['serial']}:"
        lexical = HASH_SEED
        for char in prefix:
            lexical = (lexical ^ ord(char)) * HASH_MULTIPLIER & MASK64
        padding = ord("a") + key["serial"] % 26
        for _ in range(characters - len(prefix)):
            lexical = (lexical ^ padding) * HASH_MULTIPLIER & MASK64
        checksum = (checksum ^ (key["id"] & MASK64)) * HASH_MULTIPLIER & MASK64
        checksum = (checksum ^ lexical) * HASH_MULTIPLIER & MASK64
    return format(checksum, "x")


def read_attempt(path):
    path = path.resolve(strict=True)
    process = json.loads((path / "process.json").read_text())
    require(process["exitCode"] == 0 and process["timedOut"] is False
            and process["inputsUnchanged"] is True and process["comparisonSample"] is False,
            f"Incomplete, changed-input, or misclassified process: {path}")
    for name, expected in process["rawHashes"].items():
        require(sha(path / name) == expected, f"Raw hash differs: {path / name}")
    receipt = json.loads((path / "validation.json").read_text())
    require(receipt["status"] == "pass", f"Per-invocation validation failed: {path}")
    for source, expected in receipt["runner_sources"].items():
        require(sha(Path(source)) == expected, f"Runner source changed: {source}")
    records = [json.loads(line) for line in (path / "stdout.jsonl").read_text().splitlines()
               if line.startswith("{")]
    require(len(records) == 19, f"Expected exactly 19 structured records: {path}")
    metadata, summary = records[0], records[-1]
    rounds = records[1:-1]
    require(metadata["kind"] == "natural-gc-metadata" and summary["kind"] == "natural-gc-summary",
            f"Wrong metadata/summary sequence: {path}")
    case = metadata["arm"], metadata["characters_per_key"], metadata["consumer"]
    require(case in EXPECTED, f"Unexpected cohort case: {case}")
    require(case == (summary["arm"], summary["characters"], summary["consumer"]), f"Case mismatch: {path}")
    require(case == (receipt["arm"], receipt["characters"], receipt["consumer"]), f"Receipt case mismatch: {path}")
    command = json.loads((path / "command.json").read_text())["argv"]
    require(command[-5:] == [MAIN, case[0], str(case[1]), case[2], str(path / "store" / "values")],
            f"Command/data path differs: {path}")
    require(all(flag in command for flag in ("-Xms128m", "-Xmx128m", "-XX:+UseG1GC")), f"JVM flags differ: {path}")
    normalized_command = ["<gc-log>" if value.startswith("-Xlog:gc:file=") else value for value in command[:-4]]
    gc_log = (path / "gc.log").read_text()
    require("Using G1" in gc_log and EXPLICIT_GC.search(gc_log) is None, f"GC cause/collector differs: {path}")
    require(metadata["heap_max_bytes"] == metadata["heap_initial_bytes"] == 128 << 20
            and metadata["native_map_bytes"] == 128 << 20, f"Heap/native-map size differs: {path}")
    require(metadata["keys"] == 8 and metadata["rounds_after_initial"] == 16
            and metadata["pressure_array_payload_bytes_per_round"] == 32 << 20
            and metadata["pressure_array_bytes"] == 256 << 10 and metadata["pressure_arrays_per_round"] == 128,
            f"Pressure or key-count protocol differs: {path}")
    require(metadata["source_cache_settings_changed"] is False and metadata["explicit_gc_requested"] is False,
            f"Source/collection protocol differs: {path}")
    keys = metadata["keys_and_slots"]
    require(len(keys) == 8 and len({key["id"] for key in keys}) == 8 and len({key["slot"] for key in keys}) == 8,
            f"Seed does not have eight distinct nonconflicting IDs: {path}")
    require(all(slot(key["id"]) == key["slot"] for key in keys), f"Recorded buckets do not match the full-key hash: {path}")
    require(summary["requests"] == 136 and summary["pressure_rounds"] == 16
            and summary["pressure_array_payload_bytes"] == 512 << 20, f"Totals differ: {path}")
    require(summary["ledger_after_close"] == summary["manager_after_close"] == 0
            and summary["source_closed"] is True, f"Cleanup failed: {path}")
    expected_reservation = 0 if case[0] == "ordinary" else 147536 if case[0] == "strong" else 606448
    require(summary["peak_ledger_bytes"] == expected_reservation, f"Reservation peak differs: {path}")
    calls = cold = identities = cleared_values = cleared_payloads = canaries = 0
    previous_original_values = previous_original_payloads = previous_gc_count = previous_gc_millis = 0
    previous_hits = 0
    for ordinal, row in enumerate(rounds):
        require(row["kind"] == "natural-gc-round" and row["round"] == ordinal, f"Missing/reordered round: {path}")
        require(row["checksum_hex"] == summary["checksum_hex"], f"Checksum changed between rounds: {path}")
        masks = {key: value for key, value in row.items() if key.endswith("_mask")}
        require(len(masks) == 8 and all(isinstance(value, int) and 0 <= value <= 255 for value in masks.values()),
                f"Invalid observation mask: {path}")
        require(0 <= row["cold_to_initialized_observations"] <= row["source_calls"] <= 8
                and row["returned_cold_mask"].bit_count() == row["cold_to_initialized_observations"],
                f"Invalid source/completion counts: {path}")
        calls += row["source_calls"]
        cold += row["cold_to_initialized_observations"]
        identities += row["same_previous_identity_mask"].bit_count()
        cleared_values += row["previous_values_cleared_before_demand_mask"].bit_count()
        cleared_payloads += row["previous_payloads_cleared_before_demand_mask"].bit_count()
        canaries += int(row["canary_cleared"])
        require(row["source_calls_cumulative"] == calls and row["ledger_bytes"] == expected_reservation,
                f"Cumulative call/reservation count differs: {path}")
        probes = 0 if case[0] == "ordinary" else (ordinal + 1) * 8
        hits = 0 if case[0] == "ordinary" else probes - calls
        require(row["memo_probes_cumulative"] == probes and row["memo_hits_cumulative"] == hits,
                f"Source/hit identity differs: {path}")
        require(row["same_previous_identity_mask"].bit_count() >= hits - previous_hits,
                f"A hit did not preserve the earlier representative: {path}")
        previous_hits = hits
        require(row["previous_values_cleared_before_demand_mask"] & ~row["previous_values_cleared_at_lookup_mask"] == 0
                and row["same_previous_identity_mask"] & row["previous_values_cleared_at_lookup_mask"] == 0
                and row["same_original_identity_mask"] & row["original_values_cleared_before_demand_mask"] == 0,
                f"Weak observer/identity assertions conflict: {path}")
        require(previous_original_values & ~row["original_values_cleared_before_demand_mask"] == 0
                and previous_original_payloads & ~row["original_payloads_cleared_before_demand_mask"] == 0,
                f"Original clearing is not monotonic: {path}")
        previous_original_values = row["original_values_cleared_before_demand_mask"]
        previous_original_payloads = row["original_payloads_cleared_before_demand_mask"]
        require(row["gc_count_since_reopen"] >= previous_gc_count
                and row["gc_millis_since_reopen"] >= previous_gc_millis, f"GC totals decreased: {path}")
        previous_gc_count, previous_gc_millis = row["gc_count_since_reopen"], row["gc_millis_since_reopen"]
        if ordinal == 0:
            require(row["source_calls"] == row["cold_to_initialized_observations"] == 8
                    and row["returned_cold_mask"] == 255, f"Reopen was not cold: {path}")
        if case[2] == "one":
            require((previous_original_values | previous_original_payloads) & 1 == 0,
                    f"Intentional consumer's original value/payload cleared: {path}")
            if ordinal:
                require(row["same_original_identity_mask"] & 1 == 1, f"Held memo representative changed: {path}")
    require(summary["source_calls"] == calls and summary["cold_to_initialized_observations"] == cold
            and summary["source_returned_cold"] == cold
            and summary["source_returned_initialized"] + cold == calls, f"Completion totals differ: {path}")
    require(summary["same_previous_identity_returns"] == identities
            and summary["previous_value_cleared_observations"] == cleared_values
            and summary["previous_payload_cleared_observations"] == cleared_payloads
            and summary["cleared_canaries"] == canaries, f"Identity/clearing totals differ: {path}")
    require(summary["gc_count_delta"] >= previous_gc_count and summary["gc_millis_delta"] >= previous_gc_millis,
            f"Final GC snapshot precedes the last round: {path}")
    memo = summary["memo"]
    if case[0] == "ordinary":
        require(memo is None and calls == 136 and summary["same_previous_identity_from_source"] == identities,
                f"Ordinary source control differs: {path}")
    else:
        require(memo["probes"] == 136 and memo["hits"] == 136 - calls
                and memo["capacity_at_close"] == 4096 and memo["occupied_slots_at_close"] == 8
                and memo["peak_reservation_bytes"] == expected_reservation and memo["reserved_after_close"] == 0,
                f"Memo totals or cleanup differ: {path}")
        if case[0] == "strong":
            require(calls == 8 and memo["collected_misses"] == memo["weak_entry_allocations"] == 0,
                    f"Strong retention control lost representatives: {path}")
        else:
            require(memo["collected_misses"] == calls - 8 and memo["weak_entry_allocations"] == calls,
                    f"Weak collection/source-call reconciliation differs: {path}")
    return {
        "case": case, "path": str(path), "metadata": metadata, "summary": summary,
        "normalized_command": normalized_command, "input_manifest": (path / "inputs.json").read_bytes(),
        "runner_sources": receipt["runner_sources"],
        "raw_hashes": {**process["rawHashes"], "process.json": sha(path / "process.json"),
                       "validation.json": sha(path / "validation.json")},
        "gc_log_event_ids": len(set(re.findall(r"GC\((\d+)\)", gc_log))),
        "round_observations": [{key: row[key] for key in (
            "round", "source_calls", "cold_to_initialized_observations", "same_previous_identity_mask",
            "same_original_identity_mask", "previous_values_cleared_before_demand_mask",
            "original_values_cleared_before_demand_mask", "previous_payloads_cleared_before_demand_mask",
            "original_payloads_cleared_before_demand_mask", "previous_values_cleared_at_lookup_mask",
            "returned_cold_mask", "canary_cleared",
        )} for row in rounds],
    }


def verify_inputs(raw):
    manifest = json.loads(raw)
    files = []
    for base, value in manifest.items():
        if isinstance(value, str):
            files.append((Path(base), value))
        else:
            require(isinstance(value, dict), "Unknown input identity format")
            files.extend((Path(base) / relative, expected) for relative, expected in value.items())
    for path, expected in files:
        require(path.is_file() and sha(path) == expected, f"Captured runtime input differs: {path}")
    return {"files": len(files), "bytes": sum(path.stat().st_size for path, _ in files),
            "manifest_sha256": hashlib.sha256(raw).hexdigest()}


def report(audit, directory):
    lines = [
        "# Natural collection and reuse through the real ValueStore", "",
        "## Scope and verification", "",
        "This is an untimed direct-memo diagnostic of ten fresh JVMs: strong/weak retention across two IRI sizes "
        "and zero/one intentional consumers, plus an ordinary source-only control for each size with no retained "
        "consumer. Each run reopens its seeded ValueStore, uses eight distinct noncolliding stored IDs, validates "
        "every lexical character, and issues 136 lookups over an initial read and 16 revisits. The retained sample "
        "is one Value at key index zero; these runs do not exercise retained query rows.", "",
        "Every JVM used a fixed 128 MiB G1 heap. Each revisit followed 32 MiB of volatile-escaping byte-array "
        "payload allocation, for 512 MiB per run and 5 GiB over the cohort; array headers and all other allocation "
        "are additional. Default source-cache settings were preserved. The native map size was 128 MiB, separate "
        "from the Java heap. No explicit collection cause appears in any GC log.", "",
        "The independent audit re-read the raw records and hashes, reconciled 170 rounds and 1,360 requests, "
        "and regenerated both payload-group checksums from primitive seed metadata. All ledger endpoints were "
        "zero and every source closed successfully. Corresponding seed IDs, serials, buckets, and checksums "
        "matched across the five runs at each payload size. All runs shared the captured runtime inputs and "
        "the same JVM command apart from arm, payload size, consumer, and output paths.", "",
        "The machine-readable evidence is [audit.json](audit.json). No weak clearing count was required in advance.", "",
    ]
    for characters in (1024, 1048577):
        lines.extend([f"## {characters:,}-character IRIs", "",
                      "| Arm | Consumer | Source calls | Cold completions | Same-prior returns | Memo collected misses | Original Values cleared before last revisit |",
                      "| --- | --- | ---: | ---: | ---: | ---: | ---: |"])
        for run in audit["runs"]:
            arm, chars, consumer = run["case"]
            if chars != characters:
                continue
            summary = run["summary"]
            memo = summary["memo"]
            cleared = run["round_observations"][-1]["original_values_cleared_before_demand_mask"].bit_count()
            lines.append(f"| {arm} | {consumer} | {summary['source_calls']:,} | "
                         f"{summary['cold_to_initialized_observations']:,} | "
                         f"{summary['same_previous_identity_returns']:,} | "
                         f"{memo['collected_misses'] if memo is not None else '—'} | {cleared}/8 |")
        lines.append("")
        for consumer in ("none", "one"):
            strong = next(run for run in audit["runs"] if tuple(run["case"]) == ("strong", characters, consumer))
            weak = next(run for run in audit["runs"] if tuple(run["case"]) == ("weak", characters, consumer))
            extra_calls = weak["summary"]["source_calls"] - strong["summary"]["source_calls"]
            extra_cold = weak["summary"]["cold_to_initialized_observations"] - strong["summary"]["cold_to_initialized_observations"]
            lines.append(f"With `{consumer}` retained consumers, weak recorded {extra_calls:,} additional source "
                         f"calls and {extra_cold:,} additional cold-to-initialized observations relative to strong "
                         f"in these two runs. Its memo recorded {weak['summary']['memo']['collected_misses']:,} "
                         "collected same-key entries. No collision, admission cutoff, or resize participates "
                         "in this 136-probe comparison.")
            lines.append("")
    lines.extend([
        "## Interpretation", "",
        "A cold completion means the returned native wrapper was observed uninitialized before lexical "
        "consumption and initialized afterward. It is not an instrumented count of physical LMDB decoding or "
        "storage reads. Source calls include both cold and already-initialized returns; the ordinary controls "
        "show why those counts must stay separate. Same-prior identity returns are checked against weak "
        "observers without loading earlier Values into new strong locals.", "",
        "Because the eight memo buckets do not collide and the short trace never reaches an adaptation boundary, "
        "additional weak memo misses reconcile exactly to collected entries. Clearing masks observed before "
        "demand provide direct reachability evidence; more clearing can occur during later consumption. A "
        "non-cleared weak observer is not proof that an object would remain reachable under every collection "
        "schedule. An intentional retained consumer must keep its initial Value and payload alive; every "
        "one-consumer run checks that specific key throughout all revisits.", "",
        "GC count/time deltas and whole-JVM heap snapshots include runtime and other roots. The GC log covers "
        "the entire JVM, including seeding, while recorded deltas begin after reopen and memo construction and "
        "extend through cleanup. They are not exclusive memo costs. The isolated memo ledger covers declared "
        "metadata; its zero endpoint does not assert that all source-cache or native memory was freed. These "
        "single-process cases are mechanism observations, not a query-latency estimate or a statistical "
        "comparison of collection schedules.", "",
        "## Raw runs", "",
        "| Case | GC count delta | Cleared canaries / 16 | Source returned initialized | Raw evidence |",
        "| --- | ---: | ---: | ---: | --- |",
    ])
    for run in audit["runs"]:
        summary = run["summary"]
        label = "/".join(map(str, run["case"]))
        raw = Path(os.path.relpath(Path(run["path"]) / "stdout.jsonl", directory)).as_posix()
        lines.append(f"| {label} | {summary['gc_count_delta']} | {summary['cleared_canaries']}/16 | "
                     f"{summary['source_returned_initialized']} | [records]({raw}) |")
    lines.extend(["", "All raw attempts are preserved. This audit launches no Java and changes no diagnostic source.", ""])
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output-dir", type=Path, required=True)
    parser.add_argument("attempts", type=Path, nargs="+")
    args = parser.parse_args()
    require(len(args.attempts) == 10, "Supply exactly the ten predeclared attempt directories")
    require(not args.output_dir.exists(), "Refusing to overwrite an existing analysis directory")
    runs = [read_attempt(path) for path in args.attempts]
    require(len({tuple(run["case"]) for run in runs}) == 10
            and {tuple(run["case"]) for run in runs} == EXPECTED, "Cohort has missing/duplicate/extra cases")
    require(all(run["input_manifest"] == runs[0]["input_manifest"] for run in runs), "Runtime manifests differ")
    require(all(run["normalized_command"] == runs[0]["normalized_command"] for run in runs), "JVM command differs")
    require(all(run["runner_sources"] == runs[0]["runner_sources"] for run in runs), "Runner sources differ")
    source_cache_settings = [(run["metadata"]["default_source_value_cache_size"],
                              run["metadata"]["default_source_value_id_cache_size"]) for run in runs]
    require(len(set(source_cache_settings)) == 1, "Source-cache settings differ across cases")
    expected_checksums = {}
    for characters in (1024, 1048577):
        group = [run for run in runs if run["case"][1] == characters]
        keys = group[0]["metadata"]["keys_and_slots"]
        require(all(run["metadata"]["keys_and_slots"] == keys for run in group), "Seed keys differ within payload group")
        expected = checksum_from_primitives(keys, characters)
        require(all(run["summary"]["checksum_hex"] == expected for run in group), "Independent checksum differs")
        expected_checksums[str(characters)] = expected
    identity = verify_inputs(runs[0]["input_manifest"])
    for run in runs:
        run.pop("input_manifest")
        run.pop("normalized_command")
    runs.sort(key=lambda run: (run["case"][1], ("ordinary", "strong", "weak").index(run["case"][0]), run["case"][2]))
    audit = {
        "status": "pass", "scope": "untimed_real_ValueStore_direct_memo_natural_GC", "runs": runs,
        "verification": {"processes": 10, "records": 190, "round_records": 170, "requests": 1360,
                         "pressure_array_payload_bytes": 10 * (512 << 20), "explicit_gc_log_matches": 0,
                         "ledger_cleanup_cases": 10, "independent_payload_checksums": expected_checksums,
                         "captured_inputs_verified": identity, "weak_collection_count_prespecified": False,
                         "source_completions_are_physical_decode_counts": False},
        "analyzer_sha256": sha(Path(__file__)),
    }
    directory = args.output_dir.resolve()
    directory.mkdir(parents=True, exist_ok=False)
    with (directory / "audit.json").open("x") as handle:
        json.dump(audit, handle, indent=2, sort_keys=True)
        handle.write("\n")
    (directory / "RESULTS.md").write_text(report(audit, directory))
    print(json.dumps({"status": "pass", "output": str(directory), **audit["verification"]}, sort_keys=True))


if __name__ == "__main__":
    main()
